import calendar from "./generated/calendar.bn.json";
import bnCopy from "./generated/copy.bn.json";
import type { Lang } from "./lang";

/*
 * Numbers, dates and times as the Java pages write them (UiCopy, BanglaDate). Every name and digit comes from
 * calendar.bn.json and the copy bundles, both generated by Java tests, and every function is held to Java's own output
 * by bangla-vectors.json. Nothing here is HTML-escaped: React escapes.
 */

const ASCII_DIGITS = "0123456789";
const BANGLA_DIGITS = [...calendar.digits];
if (BANGLA_DIGITS.length !== 10) throw new Error("calendar.bn.json: digits must hold ten digits");
if (calendar.months.length !== 12) throw new Error("calendar.bn.json: months must hold twelve months");

/** ASCII digits to Bangla numerals, every other character unchanged (BanglaDate.digits). */
export function banglaDigits(text: string): string {
  let out = "";
  for (const c of text) {
    const d = ASCII_DIGITS.indexOf(c);
    out += d >= 0 ? BANGLA_DIGITS[d] : c;
  }
  return out;
}

type Day = { year: number; month: number; day: number };

/** A strict ISO local date (yyyy-MM-dd) that exists on the calendar, as Java's LocalDate.parse accepts it; else null. */
function parseIso(text: string): Day | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!m) return null;
  const [year, month, day] = [Number(m[1]), Number(m[2]), Number(m[3])];
  if (month < 1 || month > 12 || day < 1) return null;
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const length = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]!;
  return day <= length ? { year, month, day } : null;
}

function isoDay(isoDate: string): Day {
  const d = parseIso(isoDate);
  if (!d) throw new Error(`not an ISO date: ${isoDate}`);
  return d;
}

const monthName = (d: Day) => calendar.months[d.month - 1]!;

/** BanglaDate.format(date, null): "day month year" in Bangla. */
function banglaFull(d: Day): string {
  return `${banglaDigits(String(d.day))} ${monthName(d)} ${banglaDigits(String(d.year))}`;
}

/** A date as a page shows it (UiCopy.dateText): the Bangla day, month and year on bn, ISO on en. */
export function formatDate(lang: Lang, isoDate: string): string {
  const d = isoDay(isoDate);
  return lang === "bn" ? banglaFull(d) : isoDate;
}

/** A date under its month header (UiCopy.dayMonthText): day and month on bn (the header has the year), ISO on en. */
export function formatDayMonth(lang: Lang, isoDate: string): string {
  const d = isoDay(isoDate);
  return lang === "bn" ? `${banglaDigits(String(d.day))} ${monthName(d)}` : isoDate;
}

const ENGLISH_MONTH = new Intl.DateTimeFormat("en-US", { month: "long", timeZone: "UTC" });

/** A month header (UiCopy.monthYear): the Bangla month and year on bn, "October 2026" on en. */
export function formatMonthYear(lang: Lang, isoDate: string): string {
  const d = isoDay(isoDate);
  if (lang === "bn") return `${monthName(d)} ${banglaDigits(String(d.year))}`;
  return `${ENGLISH_MONTH.format(Date.UTC(2000, d.month - 1, 1))} ${d.year}`;
}

/**
 * A date as printed on the paper (UiCopy.date(Lang, String)): on bn an ISO date is written as a Bangla date and any other
 * text is kept exactly as printed, never re-dated; on en the text as written.
 */
export function formatPrinted(lang: Lang, text: string): string {
  if (lang !== "bn") return text;
  if (text.trim() === "") return "";
  const d = parseIso(text.trim());
  return d ? banglaFull(d) : text;
}

const DHAKA = new Intl.DateTimeFormat("en-US", {
  timeZone: "Asia/Dhaka",
  hourCycle: "h23",
  hour: "2-digit",
  minute: "2-digit",
});

/** The copy key for the part of the day, with UiCopy.time's boundaries. */
function partOfDay(h: number) {
  if (h >= 4 && h < 6) return "time.dawn";
  if (h >= 6 && h < 12) return "time.morning";
  if (h >= 12 && h < 15) return "time.noon";
  if (h >= 15 && h < 17) return "time.afternoon";
  if (h >= 17 && h < 19) return "time.evening";
  return "time.night";
}

/**
 * A time of day on the patient's calendar, Dhaka (UiCopy.time): on bn the part of the day and a 12-hour clock in Bangla
 * digits, on en HH:mm.
 */
export function formatTime(lang: Lang, instantIso: string): string {
  const at = new Date(instantIso);
  if (Number.isNaN(at.getTime())) throw new Error(`not an instant: ${instantIso}`);
  const parts = DHAKA.formatToParts(at);
  const h = Number(parts.find((p) => p.type === "hour")?.value);
  const m = Number(parts.find((p) => p.type === "minute")?.value);
  const mm = String(m).padStart(2, "0");
  if (lang !== "bn") return `${String(h).padStart(2, "0")}:${mm}`;
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${bnCopy[partOfDay(h)]} ${banglaDigits(`${h12}:${mm}`)}`;
}
